INSERT INTO `forumCategories` (`slug`, `name`, `description`, `icon`, `color`, `sortOrder`) VALUES ('bioregions', 'Bioregions', 'Where bioregions organising for regeneration meet, share, and find each other.', 'Globe', '#d4a574', 12) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `description` = VALUES(`description`), `icon` = VALUES(`icon`), `color` = VALUES(`color`);
INSERT INTO `users` (`openId`, `name`, `email`, `role`) SELECT 'team@regencivics.earth', 'ReGen Civics Team', 'team@regencivics.earth', 'admin' WHERE NOT EXISTS (SELECT 1 FROM `users` WHERE `email` = 'team@regencivics.earth');
INSERT INTO `forumPosts` (`categoryId`, `authorId`, `title`, `content`, `isPinned`) SELECT (SELECT `id` FROM `forumCategories` WHERE `slug` = 'bioregions'), (SELECT `id` FROM `users` WHERE `email` = 'team@regencivics.earth'), 'Bioregions Organising for Regeneration', 'This is the gathering thread for bioregions actively organising for regeneration.\n\nIf you are part of a place-based effort that is healing land, weaving community, building local food economies, or experimenting with new financial and governance tooling, post here. Tell us where you are, who you are organising with, and what you are working on right now.\n\nWe are a global network that supports bioregions in tooling. The point of this thread is connection. Find each other. Compare notes. Borrow what works. Share what hurts.\n\nOne post per bioregion to start. Reply to others to start a conversation.', 1 WHERE NOT EXISTS (SELECT 1 FROM `forumPosts` WHERE `title` = 'Bioregions Organising for Regeneration');
